/* 重新配置 I2C 前先复位到默认值 */
RCC_APB1PeriphClockCmd(RCC_APB1Periph_I2C1, ENABLE);
I2C_DeInit(I2C1);

/* 注意：DeInit 不会解除 PB6/PB7 的复用开漏配置，
   重配置时要重新走一遍 GPIO_Init */

GPIO_InitTypeDef GPIO_InitStructure;
I2C_InitTypeDef I2C_InitStructure;

/* 1. 开时钟 */
RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOB, ENABLE);
RCC_APB1PeriphClockCmd(RCC_APB1Periph_I2C1, ENABLE);

/* 2. SCL=PB6, SDA=PB7，必须是复用开漏 */
GPIO_InitStructure.GPIO_Pin = GPIO_Pin_6 | GPIO_Pin_7;
GPIO_InitStructure.GPIO_Speed = GPIO_Speed_50MHz;
GPIO_InitStructure.GPIO_Mode = GPIO_Mode_AF_OD;
GPIO_Init(GPIOB, &GPIO_InitStructure);

/* 3. 配置 I2C：400kHz 主机 */
I2C_InitStructure.I2C_Mode = I2C_Mode_I2C;
I2C_InitStructure.I2C_DutyCycle = I2C_DutyCycle_2;
I2C_InitStructure.I2C_OwnAddress1 = 0x00;   /* 主机模式不重要 */
I2C_InitStructure.I2C_Ack = I2C_Ack_Enable;
I2C_InitStructure.I2C_AcknowledgedAddress = I2C_AcknowledgedAddress_7bit;
I2C_InitStructure.I2C_ClockSpeed = 400000;
I2C_Init(I2C1, &I2C_InitStructure);

/* 4. 使能 */
I2C_Cmd(I2C1, ENABLE);

I2C_InitTypeDef I2C_InitStructure;

I2C_StructInit(&I2C_InitStructure);     /* 先给默认值 */
I2C_InitStructure.I2C_ClockSpeed = 100000;  /* 默认 5000 太慢，必须改 */
I2C_Init(I2C1, &I2C_InitStructure);

I2C_Init(I2C1, &I2C_InitStructure);
I2C_Cmd(I2C1, ENABLE);   /* PE 位置 1，I2C 才真正开始工作 */

/* 清除 STOPF 的官方序列：先读 SR1，再写 CR1 */
if (I2C_GetFlagStatus(I2C1, I2C_FLAG_STOPF) != RESET)
{
  I2C_Cmd(I2C1, ENABLE);  /* 写 CR1，STOPF 被清 */
}

/* 用 DMA 发送 N 字节（地址与 START 仍需软件处理） */
DMA_InitStructure.DMA_PeripheralBaseAddr = (uint32_t)&I2C1->DR;
DMA_InitStructure.DMA_MemoryBaseAddr = (uint32_t)txBuf;
DMA_InitStructure.DMA_DIR = DMA_DIR_PeripheralDST;
DMA_InitStructure.DMA_BufferSize = N;
DMA_InitStructure.DMA_PeripheralInc = DMA_PeripheralInc_Disable;
DMA_InitStructure.DMA_MemoryInc = DMA_MemoryInc_Enable;
DMA_InitStructure.DMA_PeripheralDataSize = DMA_PeripheralDataSize_Byte;
DMA_InitStructure.DMA_MemoryDataSize = DMA_MemoryDataSize_Byte;
DMA_InitStructure.DMA_Mode = DMA_Mode_Normal;
DMA_InitStructure.DMA_Priority = DMA_Priority_High;
DMA_InitStructure.DMA_M2M = DMA_M2M_Disable;
DMA_Init(DMA1_Channel6, &DMA_InitStructure);

I2C_DMACmd(I2C1, ENABLE);
DMA_Cmd(DMA1_Channel6, ENABLE);

/* 标准的主机发送流程：每一步都必须等对应事件 */
I2C_GenerateSTART(I2C1, ENABLE);
while (!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_MODE_SELECT));  /* 等 SB */

I2C_Send7bitAddress(I2C1, 0xA0, I2C_Direction_Transmitter);
while (!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_TRANSMITTER_MODE_SELECTED)); /* 等 ADDR+TXE */

/* 主机接收 N 字节：最后一个字节前发 NACK + STOP */
I2C_AcknowledgeConfig(I2C1, DISABLE);      /* 最后 1 字节回 NACK */
I2C_GenerateSTOP(I2C1, ENABLE);
lastByte = I2C_ReceiveData(I2C1);          /* 读走即完成 */
I2C_AcknowledgeConfig(I2C1, ENABLE);       /* 恢复 ACK 供下次使用 */

/* 主机接收 2 字节，按手册的 2 字节接收流程 */
while (!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_RECEIVER_MODE_SELECTED));

/* 2 字节接收：先设 POS，再在 ADDR 后立刻关 ACK 并置 STOP */
I2C_NACKPositionConfig(I2C1, I2C_NACKPosition_Next);
I2C_AcknowledgeConfig(I2C1, DISABLE);
I2C_GenerateSTOP(I2C1, ENABLE);

while (!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_BYTE_RECEIVED));
buf[0] = I2C_ReceiveData(I2C1);
while (!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_BYTE_RECEIVED));
buf[1] = I2C_ReceiveData(I2C1);

I2C_AcknowledgeConfig(I2C1, ENABLE);   /* 恢复 ACK，否则下次读只能收到 1 字节 */

/* 从机额外响应 0x32 */
I2C_OwnAddress2Config(I2C1, 0x32);
I2C_DualAddressCmd(I2C1, ENABLE);

/* 从机同时响应 0x30 和 0x32 两个地址 */
I2C_OwnAddress2Config(I2C1, 0x32);
I2C_DualAddressCmd(I2C1, ENABLE);

I2C_GeneralCallCmd(I2C1, ENABLE);

/* 中断里判断是不是广播呼叫 */
if (I2C_GetFlagStatus(I2C1, I2C_FLAG_GENCALL) != RESET)
{
  /* 收到广播地址 */
}

/* 中断方式：先配 NVIC，再开中断源 */
NVIC_InitStructure.NVIC_IRQChannel = I2C1_EV_IRQn;
NVIC_InitStructure.NVIC_IRQChannelPreemptionPriority = 1;
NVIC_InitStructure.NVIC_IRQChannelSubPriority = 0;
NVIC_InitStructure.NVIC_IRQChannelCmd = ENABLE;
NVIC_Init(&NVIC_InitStructure);

I2C_ITConfig(I2C1, I2C_IT_EVT | I2C_IT_ERR, ENABLE);
I2C_ITConfig(I2C1, I2C_IT_BUF, ENABLE);   /* 收发数据时才开 */

/* 写寄存器：先发寄存器地址，再发数据 */
I2C_SendData(I2C1, 0x10);                               /* 寄存器地址 */
while (!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_BYTE_TRANSMITTING));

I2C_SendData(I2C1, 0x55);                               /* 数据 */
while (!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_BYTE_TRANSMITTED));
I2C_GenerateSTOP(I2C1, ENABLE);

/* 主机接收 4 字节 */
I2C_GenerateSTART(I2C1, ENABLE);
while (!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_MODE_SELECT));
I2C_Send7bitAddress(I2C1, 0x68, I2C_Direction_Receiver);
while (!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_RECEIVER_MODE_SELECTED));

for (i = 0; i < 3; i++)                     /* 前 3 字节回 ACK */
{
  while (!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_BYTE_RECEIVED));
  buf[i] = I2C_ReceiveData(I2C1);
}

I2C_AcknowledgeConfig(I2C1, DISABLE);       /* 最后一个字节回 NACK */
I2C_GenerateSTOP(I2C1, ENABLE);
while (!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_BYTE_RECEIVED));
buf[3] = I2C_ReceiveData(I2C1);
I2C_AcknowledgeConfig(I2C1, ENABLE);        /* 恢复 ACK */

/* 读 MPU6050 的 WHO_AM_I（从机地址 0x68） */
I2C_GenerateSTART(I2C1, ENABLE);
while (!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_MODE_SELECT));

/* 先写寄存器地址：方向 = 发送 */
I2C_Send7bitAddress(I2C1, 0x68, I2C_Direction_Transmitter);
while (!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_TRANSMITTER_MODE_SELECTED));
I2C_SendData(I2C1, 0x75);
while (!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_BYTE_TRANSMITTED));

/* 重复起始，方向 = 接收 */
I2C_GenerateSTART(I2C1, ENABLE);
while (!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_MODE_SELECT));
I2C_Send7bitAddress(I2C1, 0x68, I2C_Direction_Receiver);
while (!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_RECEIVER_MODE_SELECTED));

/* 调试：看 CCR 与 TRISE 算出来对不对 */
uint16_t ccr = I2C_ReadRegister(I2C1, I2C_Register_CCR);
uint16_t trise = I2C_ReadRegister(I2C1, I2C_Register_TRISE);

/* 总线卡死时的恢复流程 */
I2C_SoftwareResetCmd(I2C1, ENABLE);
I2C_SoftwareResetCmd(I2C1, DISABLE);   /* 必须成对，只 ENABLE 不复位结束 */

/* 复位后所有配置丢失，要重新初始化 */
I2C_Init(I2C1, &I2C_InitStructure);
I2C_Cmd(I2C1, ENABLE);

/* 只读 2 个字节时的标准流程 */
I2C_GenerateSTART(I2C1, ENABLE);
while (!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_MODE_SELECT));
I2C_Send7bitAddress(I2C1, 0xA1, I2C_Direction_Receiver);
while (!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_RECEIVER_MODE_SELECTED));

I2C_NACKPositionConfig(I2C1, I2C_NACKPosition_Next);  /* 只有 2 字节接收才这么设 */
I2C_AcknowledgeConfig(I2C1, DISABLE);
I2C_GenerateSTOP(I2C1, ENABLE);

while (!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_BYTE_RECEIVED));
buf[0] = I2C_ReceiveData(I2C1);
while (!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_BYTE_RECEIVED));
buf[1] = I2C_ReceiveData(I2C1);

/* 400kHz + 上拉较弱时用 16/9 占空比 */
I2C_InitStructure.I2C_ClockSpeed = 400000;
I2C_InitStructure.I2C_DutyCycle = I2C_DutyCycle_16_9;
I2C_Init(I2C1, &I2C_InitStructure);

/* 最常用的主机发送：往从机 0xA0 写 2 字节 */
I2C_GenerateSTART(I2C1, ENABLE);
while (!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_MODE_SELECT));

I2C_Send7bitAddress(I2C1, 0xA0, I2C_Direction_Transmitter);
while (!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_TRANSMITTER_MODE_SELECTED));

I2C_SendData(I2C1, regAddr);
while (!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_BYTE_TRANSMITTING));

I2C_SendData(I2C1, value);
while (!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_BYTE_TRANSMITTED));

I2C_GenerateSTOP(I2C1, ENABLE);

/* 带超时的等待，超时把实际事件打出来，方便定位卡在哪一步 */
uint32_t timeout = 100000;
I2C_GenerateSTART(I2C1, ENABLE);
while (!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_MODE_SELECT))
{
  if (--timeout == 0)
  {
    /* 打印实际事件值，与 I2C_EVENT_xxx 宏比对 */
    printf("I2C stuck, last event = 0x%08X\r\n", I2C_GetLastEvent(I2C1));
    break;
  }
}

/* 发 START 前确认总线空闲，避免 START 被忽略 */
if (I2C_GetFlagStatus(I2C1, I2C_FLAG_BUSY) == RESET)
{
  I2C_GenerateSTART(I2C1, ENABLE);
}

/* 判断从机是否应答 */
if (I2C_GetFlagStatus(I2C1, I2C_FLAG_AF) != RESET)
{
  /* 从机没应答：地址错或设备没接 */
}

/* 应答失败后的恢复流程 */
if (I2C_GetFlagStatus(I2C1, I2C_FLAG_AF) != RESET)
{
  I2C_ClearFlag(I2C1, I2C_FLAG_AF);
  I2C_GenerateSTOP(I2C1, ENABLE);   /* 清 AF 后必须补 STOP，释放总线 */
}

void I2C1_EV_IRQHandler(void)
{
  if (I2C_GetITStatus(I2C1, I2C_IT_ADDR) != RESET)
  {
    /* 读 SR1 + 读 SR2 已由本函数完成，ADDR 自动清除 */
  }
  if (I2C_GetITStatus(I2C1, I2C_IT_RXNE) != RESET)
  {
    buf[idx++] = I2C_ReceiveData(I2C1);   /* 读 DR 清 RXNE */
  }
}

void I2C1_ER_IRQHandler(void)
{
  if (I2C_GetITStatus(I2C1, I2C_IT_AF) != RESET)
  {
    /* 从机没应答（设备没接或地址错），软件可清 */
    I2C_ClearITPendingBit(I2C1, I2C_IT_AF);
    I2C_GenerateSTOP(I2C1, ENABLE);
  }
  if (I2C_GetITStatus(I2C1, I2C_IT_BERR) != RESET)
  {
    I2C_ClearITPendingBit(I2C1, I2C_IT_BERR);
  }
}
